        self.limit = limit

    def __str__(self) -> str:
        base = super().__str__()
        if self.current_usage is None or self.limit is None:
            return base
        return f"{base} [current_usage={self.current_usage}, limit={self.limit}]"


class TaskTimeoutError(DoclingServiceClientError):
